-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
CREATE OR REPLACE VIEW staging.stg_tpch_erp__nation AS
with source as (

    select * from raw_tpch_erp.nation

),

final as (

    select
        cast(source.n_nationkey as INTEGER) as n_nationkey,
        cast(source.n_name as VARCHAR) as n_name,
        cast(source.n_regionkey as INTEGER) as n_regionkey,
        cast(source.n_comment as VARCHAR) as n_comment,
        source._ingested_at as _ingested_at,
        source._batch_id as _batch_id,
        'tpch_erp' as _source_system,
        MD5(COALESCE(CAST(source.n_nationkey AS TEXT), '') || '|' || COALESCE(CAST(source.n_name AS TEXT), '') || '|' || COALESCE(CAST(source.n_regionkey AS TEXT), '') || '|' || COALESCE(CAST(source.n_comment AS TEXT), '')) as _record_hash
    from source

)

select * from final;
